import java.io.*;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.*;
import org.apache.commons.text.StringSubstitutor;
import java.util.HashMap;
import java.util.Map;
import java.util.regex.Pattern;

@WebServlet("/report")
public class ReportServlet extends HttpServlet {

    private static final Pattern SAFE_TEMPLATE_NAME = Pattern.compile("^[a-zA-Z0-9_-]{1,64}$");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String templateName = req.getParameter("template");
        String userId = req.getParameter("user_id");
        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");

        if (templateName == null || !SAFE_TEMPLATE_NAME.matcher(templateName).matches()) {
            resp.sendError(400, "Invalid template name");
            return;
        }

        // Load template from database
        String template = loadTemplate(templateName);
        if (template == null) {
            resp.sendError(404, "Template not found");
            return;
        }

        // Build the report query from template
        // Templates use ${variable} syntax for substitution
        Map<String, String> params = new HashMap<>();
        params.put("user_id", userId);
        params.put("start_date", startDate);
        params.put("end_date", endDate);
        params.put("org_id", (String) req.getSession().getAttribute("org_id"));

        StringSubstitutor sub = new StringSubstitutor(params);
        String query = sub.replace(template);

        // Execute report query
        try (Connection conn = getConnection();
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            resp.setContentType("text/html; charset=UTF-8");
            PrintWriter out = resp.getWriter();
            out.println("<html><body><table>");

            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();

            out.println("<tr>");
            for (int i = 1; i <= cols; i++) {
                out.println("<th>" + escapeHtml(meta.getColumnName(i)) + "</th>");
            }
            out.println("</tr>");

            int rowCount = 0;
            while (rs.next() && rowCount < 1000) {
                out.println("<tr>");
                for (int i = 1; i <= cols; i++) {
                    out.println("<td>" + escapeHtml(rs.getString(i)) + "</td>");
                }
                out.println("</tr>");
                rowCount++;
            }
            out.println("</table></body></html>");

        } catch (SQLException e) {
            resp.sendError(500, "Report generation failed");
        }
    }

    private String loadTemplate(String name) {
        try (Connection conn = getConnection();
             PreparedStatement ps = conn.prepareStatement(
                 "SELECT query_template FROM report_templates WHERE name = ? AND active = true")) {
            ps.setString(1, name);
            ResultSet rs = ps.executeQuery();
            if (rs.next()) return rs.getString(1);
        } catch (SQLException e) { /* log */ }
        return null;
    }

    private Connection getConnection() throws SQLException {
        return DriverManager.getConnection(
            System.getenv("JDBC_URL"),
            System.getenv("DB_USER"),
            System.getenv("DB_PASS"));
    }

    private String escapeHtml(String s) {
        if (s == null) return "";
        return s.replace("&", "&amp;").replace("<", "&lt;")
                .replace(">", "&gt;").replace("\"", "&quot;");
    }
}
